+    padding: 0.85rem 1rem;
+    display: flex;
+    flex-direction: column;
+    min-width: 0;
+  }
+  .gramaire-tryout .tryout-cap {
+    font-family: "IBM Plex Mono", ui-monospace, monospace;
+    font-size: 0.68rem;
+    color: var(--sl-color-gray-3, #7d8d85);
+    margin-bottom: 0.75rem;
+  }
+  .gramaire-tryout .tryout-diagrams {
+    flex: 1;
+    display: flex;
+    flex-direction: column;
+    gap: 0.75rem;
+    justify-content: center;
+    overflow: auto;
+  }
+  .gramaire-tryout .tryout-foot {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    flex-wrap: wrap;
